    content: `Q: 담임메모에서 자리 배치로 학생을 선택할 수 있나요?\nA: 네! 담임메모(학생 기록) 입력 화면에서 학생 선택 영역 상단의 "번호 순" / "자리 배치" 토글을 사용하면 실제 좌석 배치도를 보면서 학생을 선택할 수 있어요.`,
