    content: `Q: 특정 학생을 앞자리에 앉히려면?\nA: 설정(⚙️) → 좌석 → "좌석 관계 설정"에서 "영역 고정"을 선택하세요. 맨앞줄, 앞 2줄, 뒤 2줄, 왼쪽/오른쪽, 가운데 등 영역을 지정할 수 있어요.`,
