    content: `Q: Google Drive 동기화를 처음 설정하려면?\nA: 1) 설정(⚙️) → Google 연동으로 이동 → 2) "Google 계정 연동" 버튼 클릭 → 3) Google 로그인 및 권한 허용 → 4) 동기화가 자동으로 시작돼요. 데이터가 Google Drive에 백업되고, 다른 기기에서도 같은 계정으로 접근할 수 있어요.`,
