    content: `Q: Google Drive 동기화를 해제하려면?\nA: 설정(⚙️) → Google 연동 → "연동 해제" 버튼을 클릭하세요. 해제해도 로컬 데이터는 그대로 유지돼요. Google Drive에 저장된 백업 파일도 삭제되지 않아요.`,
    metadata: { source: 'system-qa', category: 'sync', title: 'Q: Google Drive 동기화 해제' },
