    content: `Q: 석식(저녁 급식)은 추가할 수 없나요? / 석식도 볼 수 있나요? / 저녁 급식이 안 보여요.\nA: 석식도 지원해요! 두 가지 경로로 동작합니다.\n\n① **NEIS(나이스) 자동 연동** — 학교가 NEIS에 석식을 등록해 두었다면, 급식 화면에 중식과 함께 석식이 자동으로 표시돼요. 조식도 마찬가지예요. 많은 학교가 중식만 NEIS에 올리기 때문에, 석식이 안 보인다면 학교가 NEIS에 석식을 등록하지 않은 경우가 대부분이에요.\n\n② **직접 입력** — NEIS에 석식이 없어도, 급식 화면에서 날짜 아래 [수동 입력] 버튼을 누르면 조식·중식·석식·간식 중 골라 메뉴를 직접 적을 수 있어요. CSV 파일로 한 번에 불러오는 것도 가능합니다.\n\n급식 화면 우측 상단의 출처를 "자동(NEIS + 수동)"으로 두면, NEIS가 주는 끼니와 직접 입력한 끼니가 끼니별로 합쳐져서 같이 표시돼요. (예: NEIS 중식 + 직접 입력한 석식 → 둘 다 표시)`,
    metadata: { source: 'system-qa', category: 'meal', title: 'Q: 석식(저녁 급식) 추가·표시 방법' },
