    content: `🪟 위젯 카드 클릭 → 큰 창 한 개로 통합 + 인라인 CRUD (v2.0.8 신규): 위젯 카드를 클릭하면 그 위젯 전용 큰 창(모달)이 열려 메인 앱을 안 켜고도 추가·수정·삭제까지 처리. (1) 할 일 — 새 할 일 추가, 체크 토글, 인라인 편집, 5초 Undo. (2) 메모 — 그리드에서 골라 우측 패널 편집, 한 줄 추가. (3) 미니 캘린더 — 큰 캘린더 + 우측 일정 패널 + 빠른 일정 폼 + 5초 Undo. (4) 다가오는 일정 — 인라인 일정 편집 + 빠른 추가. (5) D-Day 카운터 — 인라인 편집. (Phase 4) 담임 메모장·북마크·즐겨찾기 도구도 같은 확장 편집기. 위젯 모드(바탕화면 모드 포함)에서도 모달 안 버튼·입력 정상 동작.`,
