    content: `⌨️ 위젯 모드 ESC + 모달 버튼 + 모드 전환 + 휠 방향 핫픽스 묶음 (v2.0.8): (1) 위젯 모드(일반 BrowserWindow + 바탕화면 WS_CHILD)에서 WidgetModal·WidgetSettingsPanel이 ESC로 안 닫히던 버그 — 일반은 window.focus + capture keydown, 바탕화면은 globalShortcut IPC 폴백으로 해소. (2) 위젯 모드에서 모달 안 버튼이 안 눌리던 회귀(readOnly 가드 부작용) 해소. (3) 모드 전환 시 위젯 크기·위치가 어긋나던 회귀 — 직전 bounds 캡처 후 강제 복원. (4) 좁은 폭에서 시계가 모드 칩·설정 버튼과 겹치던 헤더 — 3열 그리드 재구성. (5) 위젯 모드 마우스 휠 상하 방향이 일반 윈도우와 반대였던 버그 — blink WebMouseWheelEvent convention SSOT 헬퍼 추출(ADR-007). (6) 미니 캘린더 모달 좁은 폭 깨짐 — md(768px) breakpoint 세로 스택. (7) 바탕화면 정리 위젯이 잘못 모달로 열리던 동작 차단.`,
